#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Google Health API access for one deployment's nightly sync.
# ──────────────────────────────────────────────────────────────────────────

SCOPE_SLEEP="https://www.googleapis.com/auth/googlehealth.sleep.readonly"
SCOPE_ACTIVITY="https://www.googleapis.com/auth/googlehealth.activity_and_fitness.readonly"
# Google spells this one both ways across its own docs, so the picker decides it.
SCOPE_METRICS_DEFAULT="https://www.googleapis.com/auth/googlehealth.health_metrics_and_measurements.readonly"

json_field() {
  local field="$1" body="$2"
  if command -v python3 >/dev/null 2>&1; then
    printf '%s' "$body" | python3 -I -c "import json,sys;print(json.load(sys.stdin).get('$field',''))" 2>/dev/null
  else
    printf '%s' "$body" | sed -n "s/.*\"$field\"[[:space:]]*:[[:space:]]*\"\([^\"]*\)\".*/\1/p"
  fi
}

# Secrets resolve per GitHub Environment here (sync.yml runs `environment: <profile>`), never at repo level.
set_env_secret() {
  local name="$1" value="$2" env_name="$3"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" --env "$env_name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name ($env_name)")
      printf '  %s✓ set%s GitHub secret %s in environment %s\n' "$GREEN" "$RESET" "$name" "$env_name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (gh secret set $name --env $env_name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

run_wizard() {

TOTAL_STAGES=7

# Only the owner wears a tracker overnight; the second athlete's watch is off for sleep.
PROFILE="adam"
ENV_FILE=".env.$PROFILE.local"

banner "Google Health API access"

stage "Google Cloud: project and API"
# gh infers the repository from the working directory, and ENV_FILE is written relative to it.
if [[ ! -f package.json || ! -d .github/workflows ]]; then
  warn "Run this from the RunOmics-Private repository root."
  exit 1
fi
say "Local values go to $ENV_FILE; CI values go to the '$PROFILE' GitHub Environment."
say "The Health API is read through an ordinary Google Cloud project."
open_url "https://console.cloud.google.com/projectcreate"
step "Create a project (or pick an existing one). Name it something like runomics-$PROFILE."
step "With that project selected, enable the Google Health API at the page opening next."
pause "Press Enter once the project exists"
open_url "https://console.cloud.google.com/apis/library/health.googleapis.com"
step "Click Enable."
pause "Press Enter once the API is enabled"

stage "OAuth client"
say "This identifies the sync to Google. The redirect URI must be exactly https://www.google.com."
open_url "https://console.cloud.google.com/auth/clients/create"
step "Application type: Web application."
step "Under 'Authorised redirect URIs', add:  https://www.google.com"
step "Create, then copy the two values it shows."
ask GOOGLE_HEALTH_CLIENT_ID "Paste the Client ID:"
ask_secret GOOGLE_HEALTH_CLIENT_SECRET "Paste the Client secret:"
write_env GOOGLE_HEALTH_CLIENT_ID "$GOOGLE_HEALTH_CLIENT_ID"
write_env GOOGLE_HEALTH_CLIENT_SECRET "$GOOGLE_HEALTH_CLIENT_SECRET"

stage "Scopes"
say "Three scopes cover sleep, the overnight metrics and steps."
open_url "https://console.cloud.google.com/auth/scopes"
step "Click 'Add or remove scopes' and filter for: googlehealth"
step "Tick the read-only scopes for sleep, health metrics and measurements, and activity and fitness."
step "Update, then Save."
say "Google's docs spell the metrics scope two ways; the console is right, so copy what it shows."
ask GOOGLE_HEALTH_METRICS_SCOPE "Paste the metrics scope exactly as listed [Enter for the documented one]:"
[[ -z "$GOOGLE_HEALTH_METRICS_SCOPE" ]] && GOOGLE_HEALTH_METRICS_SCOPE="$SCOPE_METRICS_DEFAULT"
write_env GOOGLE_HEALTH_METRICS_SCOPE "$GOOGLE_HEALTH_METRICS_SCOPE"

stage "Publish the app"
warn "This one matters: a project left in Testing issues refresh tokens that die after 7 days."
say "Published, the token lasts until it is revoked or goes ~6 months unused, so the nightly sync keeps working."
say "Under 100 users needs no security review, and this app has one."
open_url "https://console.cloud.google.com/auth/audience"
step "User type: External."
step "Click 'Publish app' and confirm."
if ! confirm "Does the Audience page now say 'In production'?"; then
  warn "Stop here and publish it; a Testing project will break the sync a week from now."
  exit 1
fi

stage "Link the Google Health app"
say "Google only serves the API once the account has signed in to the Google Health app at least once."
step "On the phone, open Google Health (the renamed Fitbit app) and sign in with the SAME Google account."
step "Check that last night's sleep and today's steps are showing there."
pause "Press Enter once the app shows data for that account"

stage "Consent"
say "Signing in here is what grants the sync read access."
CONSENT_SCOPE="${SCOPE_SLEEP}%20${GOOGLE_HEALTH_METRICS_SCOPE}%20${SCOPE_ACTIVITY}"
CONSENT_URL="https://accounts.google.com/o/oauth2/v2/auth?client_id=${GOOGLE_HEALTH_CLIENT_ID}&redirect_uri=https://www.google.com&response_type=code&access_type=offline&prompt=consent&scope=${CONSENT_SCOPE}"
open_url "$CONSENT_URL"
step "Sign in with that same Google account."
step "On 'Google hasn't verified this app': Advanced, then 'Go to ... (unsafe)'. It is your own app."
step "Tick every box, then Continue."
step "The browser lands on google.com. In the address bar, copy what sits between 'code=' and '&scope'."
ask_secret AUTH_CODE "Paste the authorization code:"

stage "Refresh token"
say "Trading the one-time code for the long-lived token the sync will use."
TOKEN_JSON=$(curl -sS -X POST https://oauth2.googleapis.com/token \
  -H "Content-Type: application/x-www-form-urlencoded" \
  -d "code=${AUTH_CODE}" \
  -d "client_id=${GOOGLE_HEALTH_CLIENT_ID}" \
  -d "client_secret=${GOOGLE_HEALTH_CLIENT_SECRET}" \
  -d "redirect_uri=https://www.google.com" \
  -d "grant_type=authorization_code" || true)
REFRESH_TOKEN=$(json_field refresh_token "$TOKEN_JSON")
if [[ -z "$REFRESH_TOKEN" ]]; then
  warn "Google returned no refresh token."
  note "$(json_field error "$TOKEN_JSON") $(json_field error_description "$TOKEN_JSON")"
  say "A code is single-use and expires in minutes, so re-run this wizard to get a fresh one."
  exit 1
fi
write_env GOOGLE_HEALTH_REFRESH_TOKEN "$REFRESH_TOKEN"
set_env_secret GOOGLE_HEALTH_CLIENT_ID "$GOOGLE_HEALTH_CLIENT_ID" "$PROFILE"
set_env_secret GOOGLE_HEALTH_CLIENT_SECRET "$GOOGLE_HEALTH_CLIENT_SECRET" "$PROFILE"
set_env_secret GOOGLE_HEALTH_REFRESH_TOKEN "$REFRESH_TOKEN" "$PROFILE"

ACCESS_TOKEN=$(json_field access_token "$TOKEN_JSON")
IDENTITY=$(curl -sS -H "Authorization: Bearer ${ACCESS_TOKEN}" -H "Accept: application/json" \
  "https://health.googleapis.com/v4/users/me/profile" || true)
if printf '%s' "$IDENTITY" | grep -q '"error"'; then
  warn "The token works but the API refused the first call:"
  note "$(printf '%s' "$IDENTITY" | tr -d '\n' | cut -c1-300)"
  say "Most often the account has not opened the Google Health app yet, or a scope was left unticked."
else
  printf '  %s✓%s Google Health answered for this account.\n' "$GREEN" "$RESET"
fi

finish
}

run_wizard "$@"; exit
